package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/feature-flag-service/internal/store"
	"github.com/luwa07832/feature-flag-service/internal/timeutil"
)

// getChanges answers the cross-flag change audit query. It is a pure read:
// history is never appended and identical inputs produce identical output.
// Validation order is fixed: path, from, to, flagKey, environment, flag.
func getChanges(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		if !validPathKeys(c, environment) {
			return
		}
		var from, to *int64
		if raw, provided := c.GetQuery("from"); provided {
			parsed, err := timeutil.Parse(raw)
			if err != nil {
				fail(c, http.StatusBadRequest, codeInvalidTimestamp, "from must be an RFC 3339 timestamp")
				return
			}
			from = &parsed
		}
		if raw, provided := c.GetQuery("to"); provided {
			parsed, err := timeutil.Parse(raw)
			if err != nil {
				fail(c, http.StatusBadRequest, codeInvalidTimestamp, "to must be an RFC 3339 timestamp")
				return
			}
			to = &parsed
		}
		if from != nil && to != nil && *from >= *to {
			fail(c, http.StatusBadRequest, codeInvalidTimestamp, "from must be earlier than to")
			return
		}
		flagKey := ""
		if raw, provided := c.GetQuery("flagKey"); provided {
			if !KeyPattern.MatchString(raw) {
				fail(c, http.StatusBadRequest, codeInvalidRequest, "flagKey must match [a-z0-9_-]{1,64}")
				return
			}
			flagKey = raw
		}
		envExists, err := st.EnvironmentExists(environment)
		if err != nil {
			internalFailure(c)
			return
		}
		if !envExists {
			fail(c, http.StatusNotFound, codeEnvironmentNotFound, "the environment does not exist")
			return
		}
		if flagKey != "" {
			flagExists, err := st.FlagExists(flagKey)
			if err != nil {
				internalFailure(c)
				return
			}
			if !flagExists {
				fail(c, http.StatusNotFound, codeFlagNotFound, "the flag does not exist")
				return
			}
		}
		records, err := st.EnvironmentChanges(environment, flagKey)
		if err != nil {
			internalFailure(c)
			return
		}
		items := make([]gin.H, 0)
		// latestValid tracks the latest non-tombstone record per flag while
		// walking the full append-only chain in (changed_at, id) order, so
		// action classification is independent of the from/to window.
		latestValid := make(map[string]*store.ConfigRecord)
		for i := range records {
			record := &records[i]
			if !withinChangeWindow(record.ChangedAt, from, to) {
				advanceChangeState(latestValid, record)
				continue
			}
			previous := latestValid[record.FlagKey]
			items = append(items, changeItemJSON(record, previous))
			advanceChangeState(latestValid, record)
		}
		c.JSON(http.StatusOK, gin.H{
			"environment": environment,
			"items":       items,
		})
	}
}

func withinChangeWindow(changedAt int64, from, to *int64) bool {
	if from != nil && changedAt < *from {
		return false
	}
	if to != nil && changedAt >= *to {
		return false
	}
	return true
}

func advanceChangeState(latestValid map[string]*store.ConfigRecord, record *store.ConfigRecord) {
	if record.Tombstone {
		latestValid[record.FlagKey] = nil
		return
	}
	latestValid[record.FlagKey] = record
}

// changeItemJSON renders one audit entry. previous is the preceding live
// (non-tombstone) configuration for the flag, or nil when there is none.
func changeItemJSON(record, previous *store.ConfigRecord) gin.H {
	var action string
	var before, after any
	var fields []string
	switch {
	case record.Tombstone:
		action = "deleted"
		before = changeConfigJSON(record)
		after = nil
		fields = nonNullChangeFields(record)
	case previous == nil:
		action = "created"
		before = nil
		after = changeConfigJSON(record)
		fields = nonNullChangeFields(record)
	default:
		action = "updated"
		before = changeConfigJSON(previous)
		after = changeConfigJSON(record)
		fields = changedFields(previous, record)
	}
	return gin.H{
		"flag_key":       record.FlagKey,
		"version":        record.Version,
		"changed_at":     timeutil.Format(record.ChangedAt),
		"action":         action,
		"changed_fields": fields,
		"before":         before,
		"after":          after,
	}
}

// changeConfigJSON renders a configuration object snapshot for before/after.
func changeConfigJSON(r *store.ConfigRecord) gin.H {
	return gin.H{
		"enabled":    r.Enabled,
		"percentage": r.Percentage,
		"window":     windowJSON(r.StartsAt, r.EndsAt),
	}
}

// nonNullChangeFields lists the populated fields in fixed order, used for
// created and deleted entries.
func nonNullChangeFields(r *store.ConfigRecord) []string {
	fields := []string{"enabled", "percentage"}
	if r.StartsAt != nil {
		fields = append(fields, "window.starts_at")
	}
	if r.EndsAt != nil {
		fields = append(fields, "window.ends_at")
	}
	return fields
}

// changedFields lists fields that differ between two consecutive live
// configurations, in the fixed enabled/percentage/window order.
func changedFields(before, after *store.ConfigRecord) []string {
	fields := make([]string, 0, 4)
	if before.Enabled != after.Enabled {
		fields = append(fields, "enabled")
	}
	if before.Percentage != after.Percentage {
		fields = append(fields, "percentage")
	}
	if !sameInstant(before.StartsAt, after.StartsAt) {
		fields = append(fields, "window.starts_at")
	}
	if !sameInstant(before.EndsAt, after.EndsAt) {
		fields = append(fields, "window.ends_at")
	}
	return fields
}

func sameInstant(a, b *int64) bool {
	if a == nil || b == nil {
		return a == b
	}
	return *a == *b
}
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/feature-flag-service/internal/eval"
	"github.com/luwa07832/feature-flag-service/internal/store"
	"github.com/luwa07832/feature-flag-service/internal/timeutil"
)

func listFlags(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		flags, err := st.ListFlags()
		if err != nil {
			internalFailure(c)
			return
		}
		keys := make([]string, 0, len(flags))
		for _, flag := range flags {
			keys = append(keys, flag.Key)
		}
		c.JSON(http.StatusOK, gin.H{"flags": keys})
	}
}

func getHistory(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		flagKey := c.Param("flagKey")
		if !validPathKeys(c, environment, flagKey) {
			return
		}
		exists, err := st.EnvironmentExists(environment)
		if err != nil {
			internalFailure(c)
			return
		}
		if !exists {
			fail(c, http.StatusNotFound, codeEnvironmentNotFound, "the environment does not exist")
			return
		}
		records, err := st.ConfigHistory(flagKey, environment)
		if err != nil {
			internalFailure(c)
			return
		}
		versions := make([]gin.H, 0, len(records))
		for _, record := range records {
			versions = append(versions, configJSON(record))
		}
		c.JSON(http.StatusOK, gin.H{
			"environment": environment,
			"flag_key":    flagKey,
			"versions":    versions,
		})
	}
}

// evaluate serves the existing real-time evaluation; it is deliberately the
// same evaluation core as the historical entry.
func evaluate(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		if !validPathKeys(c, environment) {
			return
		}
		marker := c.Query("marker")
		if marker == "" {
			fail(c, http.StatusBadRequest, codeInvalidMarker, "marker query parameter is required")
			return
		}
		if err := eval.ValidateMarker(marker); err != nil {
			fail(c, http.StatusBadRequest, codeInvalidMarker, "marker must match [a-z0-9_-]{1,64}")
			return
		}
		exists, err := st.EnvironmentExists(environment)
		if err != nil {
			internalFailure(c)
			return
		}
		if !exists {
			fail(c, http.StatusNotFound, codeEnvironmentNotFound, "the environment does not exist")
			return
		}
		now := st.Now()
		effective, err := st.EffectiveConfigsAt(environment, now)
		if err != nil {
			internalFailure(c)
			return
		}
		flags, err := st.ListFlags()
		if err != nil {
			internalFailure(c)
			return
		}
		results := make([]gin.H, 0, len(flags))
		for _, flag := range flags {
			record, present := effective[flag.Key]
			var live *store.ConfigRecord
			if present && !record.Tombstone {
				live = &record
			}
			results = append(results, flagJSON(environment, flag.Key, live, true, marker, now))
		}
		c.JSON(http.StatusOK, gin.H{
			"environment":  environment,
			"evaluated_at": timeutil.Format(now),
			"marker":       marker,
			"flags":        results,
		})
	}
}

// evaluateAt is the historical point-in-time restore and evaluation entry.
// Validation order is fixed so every malformed request gets a unique result:
// timestamp, then marker, then environment.
func evaluateAt(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		if !validPathKeys(c, environment) {
			return
		}
		at, err := timeutil.Parse(c.Query("at"))
		if err != nil {
			fail(c, http.StatusBadRequest, codeInvalidTimestamp, "at must be an RFC 3339 timestamp")
			return
		}
		rawMarker := c.Query("marker")
		if err := eval.ValidateMarker(rawMarker); err != nil {
			fail(c, http.StatusBadRequest, codeInvalidMarker, "marker must match [a-z0-9_-]{1,64}")
			return
		}
		exists, err := st.EnvironmentExists(environment)
		if err != nil {
			internalFailure(c)
			return
		}
		if !exists {
			fail(c, http.StatusNotFound, codeEnvironmentNotFound, "the environment does not exist")
			return
		}
		effective, err := st.EffectiveConfigsAt(environment, at)
		if err != nil {
			internalFailure(c)
			return
		}
		if !hasRestorableConfig(effective) {
			fail(c, http.StatusNotFound, codeEnvironmentNotFound, "no configuration can be restored for the environment at that time")
			return
		}
		flags, err := st.ListFlags()
		if err != nil {
			internalFailure(c)
			return
		}
		evaluated := rawMarker != ""
		results := make([]gin.H, 0, len(flags))
		for _, flag := range flags {
			record, present := effective[flag.Key]
			var restored *store.ConfigRecord
			if present && !record.Tombstone {
				restored = &record
			}
			results = append(results, flagJSON(environment, flag.Key, restored, evaluated, rawMarker, at))
		}
		response := gin.H{
			"environment": environment,
			"at":          timeutil.Format(at),
			"marker":      markerOrNull(rawMarker),
			"flags":       results,
		}
		c.JSON(http.StatusOK, response)
	}
}

// flagJSON renders one flag row. record is nil for the unconfigured state:
// the flag key is still emitted, while version, percentage, window and
// enabled are null. Without a marker every row carries the unified
// not_evaluated status; with a marker the status is definitive.
func flagJSON(environment, flagKey string, record *store.ConfigRecord, evaluated bool, marker string, at int64) gin.H {
	row := gin.H{"flag_key": flagKey}
	if record == nil {
		row["version"] = nil
		row["percentage"] = nil
		row["window"] = nil
		row["enabled"] = nil
		if evaluated {
			row["status"] = string(eval.StatusUnconfigured)
		} else {
			row["status"] = string(eval.StatusNotEvaluated)
		}
		return row
	}
	row["version"] = record.Version
	row["percentage"] = record.Percentage
	row["window"] = windowJSON(record.StartsAt, record.EndsAt)
	row["enabled"] = record.Enabled
	switch {
	case !evaluated:
		row["status"] = string(eval.StatusNotEvaluated)
	case record.Tombstone:
		row["status"] = string(eval.StatusUnconfigured)
	default:
		cfg := eval.Configuration{
			FlagKey:    record.FlagKey,
			Enabled:    record.Enabled,
			Percentage: record.Percentage,
			Window:     eval.Window{StartsAt: record.StartsAt, EndsAt: record.EndsAt},
		}
		row["status"] = string(eval.Evaluated(environment, &cfg, marker, at))
	}
	return row
}

func markerOrNull(marker string) any {
	if marker == "" {
		return nil
	}
	return marker
}

// explainFlag answers one deterministic flag decision for one marker. It is a
// pure read: it never appends history, and identical inputs always produce
// identical output. Without an at query parameter the decision uses the
// service's current time; with one it restores the last version whose
// changed_at is not later than at. Validation order is fixed: path, at,
// marker, environment, flag.
func explainFlag(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		flagKey := c.Param("flagKey")
		if !validPathKeys(c, environment, flagKey) {
			return
		}
		at := st.Now()
		if rawAt, provided := c.GetQuery("at"); provided {
			parsed, err := timeutil.Parse(rawAt)
			if err != nil {
				fail(c, http.StatusBadRequest, codeInvalidTimestamp, "at must be an RFC 3339 timestamp")
				return
			}
			at = parsed
		}
		marker := c.Query("marker")
		if marker == "" {
			fail(c, http.StatusBadRequest, codeInvalidMarker, "marker query parameter is required")
			return
		}
		if err := eval.ValidateMarker(marker); err != nil {
			fail(c, http.StatusBadRequest, codeInvalidMarker, "marker must match [a-z0-9_-]{1,64}")
			return
		}
		exists, err := st.EnvironmentExists(environment)
		if err != nil {
			internalFailure(c)
			return
		}
		if !exists {
			fail(c, http.StatusNotFound, codeEnvironmentNotFound, "the environment does not exist")
			return
		}
		flagExists, err := st.FlagExists(flagKey)
		if err != nil {
			internalFailure(c)
			return
		}
		if !flagExists {
			fail(c, http.StatusNotFound, codeFlagNotFound, "the flag does not exist")
			return
		}
		record, err := st.LatestConfigAt(flagKey, environment, at)
		if err != nil {
			internalFailure(c)
			return
		}

		var config *eval.Configuration
		var configBody any
		switch {
		case record == nil || record.Tombstone:
			configBody = nil
		default:
			config = &eval.Configuration{
				FlagKey:    record.FlagKey,
				Enabled:    record.Enabled,
				Percentage: record.Percentage,
				Window:     eval.Window{StartsAt: record.StartsAt, EndsAt: record.EndsAt},
			}
			configBody = gin.H{
				"version":    record.Version,
				"enabled":    record.Enabled,
				"percentage": record.Percentage,
				"window":     windowJSON(record.StartsAt, record.EndsAt),
			}
		}
		status, reason := eval.Explain(environment, config, marker, at)
		c.JSON(http.StatusOK, gin.H{
			"environment":  environment,
			"flag_key":     flagKey,
			"marker":       marker,
			"evaluated_at": timeutil.Format(at),
			"status":       string(status),
			"reason":       string(reason),
			"config":       configBody,
		})
	}
}

func hasRestorableConfig(effective map[string]store.ConfigRecord) bool {
	for _, record := range effective {
		if !record.Tombstone {
			return true
		}
	}
	return false
}

func internalFailure(c *gin.Context) {
	fail(c, http.StatusInternalServerError, "internal_error", "the service could not complete the request")
}

