			row["status"] = string(eval.StatusUnconfigured)
		} else {
			row["status"] = string(eval.StatusNotEvaluated)
		}
		return row
	}
	row["version"] = record.Version
	row["percentage"] = record.Percentage
	row["window"] = windowJSON(record.StartsAt, record.EndsAt)
