package store

import (
	"path/filepath"
	"testing"
	"time"
)

func int64p(v int64) *int64 { return &v }

func TestCreateFlagAppendsCreatedEvent(t *testing.T) {
	base := time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
	st, _ := openAt(t, base)

	flag, err := st.CreateFlag(CreateFlagInput{
		Key:         "checkout",
		Description: "Payments",
		Labels:      []string{"z", "a", "a"},
	})
	if err != nil {
		t.Fatalf("create: %v", err)
	}

	events, err := st.DefinitionHistory("checkout", nil, nil)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 1 {
		t.Fatalf("events = %d, want 1", len(events))
	}
	event := events[0]
	if event.Action != DefinitionActionCreated {
		t.Fatalf("action = %q", event.Action)
	}
	if event.ChangedAt != flag.CreatedAt {
		t.Fatalf("changed_at = %d, want created_at %d", event.ChangedAt, flag.CreatedAt)
	}
	if event.EventID <= 0 {
		t.Fatalf("event_id = %d, want positive", event.EventID)
	}
	if !equalStrings(event.ChangedFields, []string{"description", "labels"}) {
		t.Fatalf("changed_fields = %v", event.ChangedFields)
	}
	if event.Before != nil {
		t.Fatalf("before = %#v, want nil", event.Before)
	}
	if event.After == nil {
		t.Fatalf("after is nil")
	}
	if event.After.Description != "Payments" {
		t.Fatalf("after description = %q", event.After.Description)
	}
	if want := []string{"a", "z"}; !equalStrings(event.After.Labels, want) {
		t.Fatalf("after labels = %v, want %v", event.After.Labels, want)
	}
}

func TestUpdateFlagAppendsUpdatedEventWithActualChanges(t *testing.T) {
	base := time.Date(2026, 3, 2, 0, 0, 0, 0, time.UTC)
	st, clock := openAt(t, base)
	if _, err := st.CreateFlag(CreateFlagInput{
		Key:         "checkout",
		Description: "Before",
		Labels:      []string{"a"},
	}); err != nil {
		t.Fatalf("create: %v", err)
	}

	clock.advance(base.Add(2 * time.Hour))
	flag, err := st.UpdateFlagDefinition("checkout", "Before", []string{"b", "b", "a"})
	if err != nil {
		t.Fatalf("update: %v", err)
	}

	events, err := st.DefinitionHistory("checkout", nil, nil)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 2 {
		t.Fatalf("events = %d, want 2", len(events))
	}
	event := events[1]
	if event.Action != DefinitionActionUpdated {
		t.Fatalf("action = %q", event.Action)
	}
	if event.ChangedAt != flag.UpdatedAt {
		t.Fatalf("changed_at = %d, want updated_at %d", event.ChangedAt, flag.UpdatedAt)
	}
	if !equalStrings(event.ChangedFields, []string{"labels"}) {
		t.Fatalf("changed_fields = %v, want [labels]", event.ChangedFields)
	}
	if event.Before == nil || event.Before.Description != "Before" ||
		!equalStrings(event.Before.Labels, []string{"a"}) {
		t.Fatalf("before = %#v", event.Before)
	}
	if event.After == nil || event.After.Description != "Before" ||
		!equalStrings(event.After.Labels, []string{"a", "b"}) {
		t.Fatalf("after = %#v", event.After)
	}
	if event.EventID <= events[0].EventID {
		t.Fatalf("event ids not increasing: %d <= %d", event.EventID, events[0].EventID)
	}
}

func TestIdenticalReplacementAppendsEmptyFieldsUpdatedEvent(t *testing.T) {
	base := time.Date(2026, 3, 3, 0, 0, 0, 0, time.UTC)
	st, clock := openAt(t, base)
	created, err := st.CreateFlag(CreateFlagInput{
		Key:         "checkout",
		Description: "Same",
		Labels:      []string{"a"},
	})
	if err != nil {
		t.Fatalf("create: %v", err)
	}

	clock.advance(base.Add(time.Hour))
	updated, err := st.UpdateFlagDefinition("checkout", "Same", []string{"a"})
	if err != nil {
		t.Fatalf("update: %v", err)
	}
	if updated.UpdatedAt <= created.CreatedAt {
		t.Fatalf("updated_at = %d, want refreshed", updated.UpdatedAt)
	}

	events, err := st.DefinitionHistory("checkout", nil, nil)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 2 {
		t.Fatalf("events = %d, want 2", len(events))
	}
	event := events[1]
	if event.Action != DefinitionActionUpdated || len(event.ChangedFields) != 0 {
		t.Fatalf("event = %#v", event)
	}
	if event.Before == nil || event.After == nil {
		t.Fatalf("snapshots missing")
	}
}

func TestFailedUpdateWritesNoEvent(t *testing.T) {
	base := time.Date(2026, 3, 4, 0, 0, 0, 0, time.UTC)
	st, clock := openAt(t, base)
	clock.advance(base.Add(time.Hour))
	if _, err := st.UpdateFlagDefinition("ghost", "x", nil); err != ErrNotFound {
		t.Fatalf("update err = %v, want ErrNotFound", err)
	}
	events, err := st.DefinitionHistory("ghost", nil, nil)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 0 {
		t.Fatalf("events = %d, want 0", len(events))
	}
}

func TestDefinitionHistorySameInstantOrdersByEventID(t *testing.T) {
	base := time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC)
	st, clock := openAt(t, base)
	if _, err := st.CreateFlag(CreateFlagInput{Key: "checkout", Description: "v0"}); err != nil {
		t.Fatalf("create: %v", err)
	}
	clock.advance(base.Add(time.Hour))
	for _, description := range []string{"v1", "v2", "v3"} {
		if _, err := st.UpdateFlagDefinition("checkout", description, nil); err != nil {
			t.Fatalf("update %s: %v", description, err)
		}
	}
	events, err := st.DefinitionHistory("checkout", nil, nil)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 4 {
		t.Fatalf("events = %d, want 4", len(events))
	}
	wantDescriptions := []string{"v0", "v1", "v2", "v3"}
	for i, event := range events {
		if event.After.Description != wantDescriptions[i] {
			t.Fatalf("event %d description = %q, want %q", i, event.After.Description, wantDescriptions[i])
		}
		if i > 0 && event.EventID <= events[i-1].EventID {
			t.Fatalf("event ids not strictly increasing at %d", i)
		}
	}
}

func TestDefinitionHistoryWindowIsHalfOpen(t *testing.T) {
	t0 := time.Date(2026, 3, 6, 0, 0, 0, 0, time.UTC)
	t1 := t0.Add(time.Hour)
	t2 := t0.Add(2 * time.Hour)
	t3 := t0.Add(3 * time.Hour)
	st, clock := openAt(t, t0)
	if _, err := st.CreateFlag(CreateFlagInput{Key: "checkout", Description: "v0"}); err != nil {
		t.Fatalf("create: %v", err)
	}
	clock.advance(t1)
	if _, err := st.UpdateFlagDefinition("checkout", "v1", nil); err != nil {
		t.Fatalf("update: %v", err)
	}
	clock.advance(t2)
	if _, err := st.UpdateFlagDefinition("checkout", "v2", nil); err != nil {
		t.Fatalf("update: %v", err)
	}
	clock.advance(t3)
	if _, err := st.UpdateFlagDefinition("checkout", "v3", nil); err != nil {
		t.Fatalf("update: %v", err)
	}

	from := t1.UnixNano()
	to := t3.UnixNano()
	events, err := st.DefinitionHistory("checkout", &from, &to)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 2 {
		t.Fatalf("events = %d, want 2 (from inclusive, to exclusive)", len(events))
	}
	if events[0].After.Description != "v1" || events[1].After.Description != "v2" {
		t.Fatalf("descriptions = %s, %s", events[0].After.Description, events[1].After.Description)
	}

	events, err = st.DefinitionHistory("checkout", int64p(t2.UnixNano()), nil)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 2 || events[0].After.Description != "v2" {
		t.Fatalf("from-only events = %#v", events)
	}

	events, err = st.DefinitionHistory("checkout", nil, int64p(t1.UnixNano()))
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 1 || events[0].After.Description != "v0" {
		t.Fatalf("to-only events = %#v", events)
	}
}

func TestDefinitionHistorySurvivesRestartAppendOnly(t *testing.T) {
	path := filepath.Join(t.TempDir(), "store.db")
	base := time.Date(2026, 3, 7, 0, 0, 0, 0, time.UTC)
	clock := &fakeClock{t: base}
	st, err := OpenWithClock(path, func() time.Time { return clock.t })
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	if _, err := st.CreateFlag(CreateFlagInput{
		Key:         "checkout",
		Description: "v0",
		Labels:      []string{"a"},
	}); err != nil {
		t.Fatalf("create: %v", err)
	}
	clock.advance(base.Add(time.Hour))
	if _, err := st.UpdateFlagDefinition("checkout", "v1", []string{"b"}); err != nil {
		t.Fatalf("update: %v", err)
	}
	if err := st.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}

	reopened, err := OpenWithClock(path, func() time.Time { return clock.t })
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer reopened.Close()
	events, err := reopened.DefinitionHistory("checkout", nil, nil)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(events) != 2 {
		t.Fatalf("events after reopen = %d, want 2 (no backfill duplicates)", len(events))
	}
	if events[0].EventID != 1 || events[1].EventID != 2 {
		t.Fatalf("event ids = %d, %d", events[0].EventID, events[1].EventID)
	}
	clock.advance(base.Add(2 * time.Hour))
	if _, err := reopened.UpdateFlagDefinition("checkout", "v2", []string{"c"}); err != nil {
		t.Fatalf("post-reopen update: %v", err)
	}
